llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Safinamide, a small-molecule oral drug with aromatic amine/amide and ether functionality, has an absolute oral bioavailability of about 95% versus IV in healthy subjects, supporting high F for similarly sized, moderately polar oral molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Tolfenamic acid, an N-aryl anthranilic acid with a methyl/chloro-substituted phenyl group, has an absolute oral bioavailability of 63.2% versus IV in healthy volunteers, supporting high F for N-aryl aromatic structures related to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Bumetanide, a sulfonamide-containing aromatic drug, has an oral bioavailability of about 0.90 by AUC and urinary recovery versus IV, supporting high F for sulfonamide/sulfonylurea-related structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Isoniazid, a small pyridine-containing drug, has an absolute oral bioavailability of 93% in fasting adult TB patients, supporting high F for pyridine-containing small molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Y-20811, a tolyl-substituted heteroaromatic carboxylic acid, has an oral bioavailability of 0.72–0.81 versus IV, supporting high F for tolyl/heteroaromatic oral drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Isradipine has a low absolute oral bioavailability of 16% in healthy subjects, providing a contradictory example; however, its low F is associated with dihydropyridine ester first-pass metabolism, a motif absent from the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The preponderance of highly transferable experimental evidence from small-molecule oral drugs—including sulfonamide/sulfonylurea-related, pyridine-containing, and N-aryl analogues—shows absolute oral bioavailability well above the 20% threshold (e.g., 63–95%). The only clearly low-F analogue, isradipine, lacks the query's structural features and its first-pass liability is not expected to transfer. Therefore, the query is predicted to have high oral bioavailability.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement is available for the query molecule.",
    "No exact sulfonylurea analogue with the same pyridyl-aniline substitution pattern is present in the evidence set.",
    "Human metabolic stability of the sulfonylurea and pyridyl-aniline moieties is inferred rather than directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

